def calculate_rebalance_orders(current_holdings, target_holdings):
    all_syms = set(current_holdings.keys()) | set(target_holdings.keys())
    diff = {}
    for s in all_syms:
        cur = current_holdings.get(s, 0)
        tgt = target_holdings.get(s, 0)
        delta = tgt - cur
        if delta != 0:
            diff[s] = delta
    return diff

calculate_rebalance_orders({"A": 100, "B": 200, "C": 50}, {"A": 150, "B": 200, "D": 80})

def is_valid_state_transition(current_state, next_state):
    valid_map = {
        "PENDING": {"ACCEPTED", "REJECTED"},
        "ACCEPTED": {"PARTIAL_FILLED", "FILLED", "CANCELLED"},
        "PARTIAL_FILLED": {"PARTIAL_FILLED", "FILLED", "CANCELLED"},
        "FILLED": set(),
        "CANCELLED": set(),
        "REJECTED": set()
    }
    return next_state in valid_map.get(current_state, set())

is_valid_state_transition("PENDING", "ACCEPTED")

def check_fat_finger(order_price, market_price, max_dev=0.02):
    if market_price <= 0:
        return False
    dev = abs(order_price - market_price) / market_price
    return dev <= max_dev

check_fat_finger(101.0, 100.0, 0.02)

def check_wash_trade(new_order, pending_orders):
    s_new, buy_new, p_new = new_order
    for s_old, buy_old, p_old in pending_orders:
        if s_new == s_old and buy_new != buy_old:
            # 一个买一个卖，检查价格是否交叉
            buy_p = p_new if buy_new else p_old
            sell_p = p_old if buy_new else p_new
            if buy_p >= sell_p:
                return True
    return False

check_wash_trade(('A', False, 9.8), [('A', True, 10.0)])
